// 登记成功后，调用方复用并改写原请求中的结束时间，不能影响账本。
func TestRegisterEndImmuneToRequestMutation(t *testing.T) {
	now, setNow := fixedClock(at(0))
	b := NewBook(WithClock(now))

	end := at(10)
	req := RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 100, Start: at(0), End: &end}
	if err := b.RegisterVersion(req); err != nil {
		t.Fatal(err)
	}
	// 旧版十点结束，新版十点开始（相邻交接）
	if err := b.RegisterVersion(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 200, Start: at(10)}); err != nil {
		t.Fatal(err)
	}

	// 把原请求中的结束时刻改晚到十二点
	*req.End = at(12)
	views, err := b.ItemVersions("seat")
	if err != nil {
		t.Fatal(err)
	}
	for _, v := range views {
		if v.VersionID != "old" {
			continue
		}
		if v.End == nil || !v.End.Equal(at(10)) {
			t.Fatalf("registered end changed by request mutation: %v", v.End)
		}
		if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(10)) {
			t.Fatalf("effective end changed by request mutation: %v", v.EffectiveEnd)
		}
	}
	// 十一点旧版仍不可报价，新版可以——不能出现两版同时有效
	setNow(at(11))
	out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "old", Quantity: 1})
	if out.Confirmed || out.Reason != ReasonVersionExpired {
		t.Fatalf("old version must still expire at 10: %+v", out)
	}
	out, _ = b.Quote(QuoteRequest{RequestID: "q-new", ItemID: "seat", VersionID: "new", Quantity: 1})
	if !out.Confirmed {
		t.Fatalf("new version should be quotable at 11: %+v", out)
	}

	// 改早到八点也不能让已登记版本提前到期
	*req.End = at(8)
	views, _ = b.ItemVersions("seat")
	if views[0].End == nil || !views[0].End.Equal(at(10)) {
		t.Fatalf("registered end moved earlier by request mutation: %v", views[0].End)
	}
}

// 查询返回的登记结束时间与实际结束时间可被调用方随意修改，但账本不变。
func TestQueryMutationDoesNotChangeLedger(t *testing.T) {
	now, setNow := fixedClock(at(0))
	b := NewBook(WithClock(now))
	must := func(r RegisterRequest) {
		t.Helper()
		if err := b.RegisterVersion(r); err != nil {
			t.Fatalf("register: %v", err)
		}
	}
	must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 100, Start: at(0), End: atPtr(100)})
	must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 200, Start: at(40), Replaces: "old"})

	first, err := b.ItemVersions("seat")
	if err != nil {
		t.Fatal(err)
	}
	// old 的登记结束为 100，实际结束被截断到 40
	var old, nv *VersionView
	for i := range first {
		switch first[i].VersionID {
		case "old":
			old = &first[i]
		case "new":
			nv = &first[i]
		}
	}
	if old.End == nil || !old.End.Equal(at(100)) || old.EffectiveEnd == nil || !old.EffectiveEnd.Equal(at(40)) {
		t.Fatalf("unexpected old view: %+v", old)
	}
	if nv.End != nil || nv.EffectiveEnd != nil {
		t.Fatalf("new should be open-ended: %+v", nv)
	}

	// 调用方为展示目的改写这份查询结果
	*old.End = at(99)
	*old.EffectiveEnd = at(98)
	twelve := at(12)
	nv.End = &twelve
	nv.EffectiveEnd = &twelve

	// 再次查询仍是账本中的真实边界
	second, err := b.ItemVersions("seat")
	if err != nil {
		t.Fatal(err)
	}
	var old2, nv2 *VersionView
	for i := range second {
		switch second[i].VersionID {
		case "old":
			old2 = &second[i]
		case "new":
			nv2 = &second[i]
		}
	}
	if old2.End == nil || !old2.End.Equal(at(100)) {
		t.Fatalf("registered end changed through query mutation: %v", old2.End)
	}
	if old2.EffectiveEnd == nil || !old2.EffectiveEnd.Equal(at(40)) {
		t.Fatalf("effective end changed through query mutation: %v", old2.EffectiveEnd)
	}
	if nv2.End != nil || nv2.EffectiveEnd != nil {
		t.Fatalf("open-ended version got an end through another view: %+v", nv2)
	}

	// 第一份结果内部：登记结束与实际结束即使值相同，修改一项也不连带另一项
	equalEnd := at(100)
	must(RegisterRequest{ItemID: "hall", VersionID: "v", UnitPrice: 1, Start: at(0), End: &equalEnd})
	h1, _ := b.ItemVersions("hall")
	h2, _ := b.ItemVersions("hall")
	if h1[0].End == h1[0].EffectiveEnd {
		t.Fatal("registered end and effective end share one pointer")
	}
	if h1[0].End == h2[0].End {
		t.Fatal("separate queries share the registered-end pointer")
	}
	if h1[0].EffectiveEnd == h2[0].EffectiveEnd {
		t.Fatal("separate queries share the effective-end pointer")
	}
	*h1[0].End = at(50)
	if !h1[0].EffectiveEnd.Equal(at(100)) {
		t.Fatalf("editing registered end leaked to effective end: %v", h1[0].EffectiveEnd)
	}
	if !h2[0].End.Equal(at(100)) {
		t.Fatalf("editing one query result leaked to another: %v", h2[0].End)
	}

	// 报价仍按真实区间处理：40 起 old 已失效
	setNow(at(45))
	out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "old", Quantity: 1})
	if out.Confirmed || out.Reason != ReasonVersionExpired {
		t.Fatalf("quote must use ledger boundary: %+v", out)
	}
}

// 外部修改旧版或新版查询中的时间，不得改变替代交接点；新版到期后旧版不恢复生效。
func TestReplacementHandoffImmuneToViewMutation(t *testing.T) {
	now, setNow := fixedClock(at(0))
	b := NewBook(WithClock(now))
	must := func(r RegisterRequest) {
		t.Helper()
		if err := b.RegisterVersion(r); err != nil {
			t.Fatalf("register: %v", err)
		}
	}
	must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 1, Start: at(0), End: atPtr(100)})
	must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 1, Start: at(40), End: atPtr(60), Replaces: "old"})

	views, _ := b.ItemVersions("seat")
	for i := range views {
		if views[i].VersionID == "old" {
			*views[i].End = at(1000)
			*views[i].EffectiveEnd = at(1000)
		}
		if views[i].VersionID == "new" {
			*views[i].End = at(1000)
			*views[i].EffectiveEnd = at(1000)
		}
	}

	again, _ := b.ItemVersions("seat")
	for _, v := range again {
		switch v.VersionID {
		case "old":
			if v.End == nil || !v.End.Equal(at(100)) {
				t.Fatalf("old registered end changed: %v", v.End)
			}
			if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(40)) {
				t.Fatalf("handoff point changed: %v", v.EffectiveEnd)
			}
		case "new":
			if v.End == nil || !v.End.Equal(at(60)) {
				t.Fatalf("new registered end changed: %v", v.End)
			}
			if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(60)) {
				t.Fatalf("new effective end changed: %v", v.EffectiveEnd)
			}
		}
	}

	// 新版到期后，旧版仍止于交接点，不能恢复生效
	setNow(at(70))
	out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "old", Quantity: 1})
	if out.Confirmed || out.Reason != ReasonVersionExpired {
		t.Fatalf("superseded old must not revive: %+v", out)
	}
}

// 未提供结束时间且未被替代的版本持续有效，两种结束时间都为空；
// 之后被替代，登记结束仍为空，实际结束显示交接点。
func TestOpenEndedKeepsNilRegisteredEnd(t *testing.T) {
	b := NewBook()
	must := func(r RegisterRequest) {
		t.Helper()
		if err := b.RegisterVersion(r); err != nil {
			t.Fatalf("register: %v", err)
		}
	}
	must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 1, Start: at(0)})
	views, _ := b.ItemVersions("seat")
	if views[0].End != nil || views[0].EffectiveEnd != nil {
		t.Fatalf("open-ended version must report nil ends: %+v", views[0])
	}

	must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 1, Start: at(40), Replaces: "old"})
	views, _ = b.ItemVersions("seat")
	// 即使调用方给返回结果中的登记结束塞了值，再次查询仍应为 nil
	for i := range views {
		if views[i].VersionID == "old" {
			late := at(99)
			views[i].End = &late
			*views[i].EffectiveEnd = at(99)
		}
	}
	again, _ := b.ItemVersions("seat")
	for _, v := range again {
		if v.VersionID == "old" {
			if v.End != nil {
				t.Fatalf("registered end must stay nil after replacement: %v", v.End)
			}
			if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(40)) {
				t.Fatalf("effective end should show handoff: %v", v.EffectiveEnd)
			}
		}
	}
}

# 本地费率版本与报价

`tariff` 是一个在本机运行的费率版本与报价账本（`tariff.Book`），支持：

- 按费率项登记带整数分单价、生效起点和结束时刻（不含）的费率版本；
- 登记一个**替代旧版本**的新版本，账本自动把旧版本的实际有效期截断到交接时刻；
- 在指定时刻对指定版本报价，得到**首次受理结果**（确认并给出单价、总价，或带原因拒绝）；
- 按请求标识进行幂等重试和事后查询——费率变化后可据此核对一笔报价应沿用原请求标识还是发起新报价。

## 测试

```bash
go test ./...
```

测试通过表示包可以加载且现有行为符合预期。

## 费率变化后如何核对一笔报价

### “报价被拒绝”和“调用返回错误”是两回事

`Quote` 的返回值是 `(tariff.Outcome, error)`：

- **`error` 非空**：调用本身不成立，例如相同请求标识此前提交过不同的请求内容（`tariff.ErrRequestIDConflict`）。此时没有可使用的报价结果。
- **`error` 为空但 `Outcome.Confirmed == false`**：报价已被受理、但被**拒绝**，拒绝原因在 `Outcome.Reason`（如 `version_expired`、`version_not_yet_effective`、`version_not_found`、`invalid_quantity`、`total_overflow`、`empty_request_id`）。

因此**不能仅凭 `err == nil` 判断成功**，必须检查 `Confirmed`。引用已失效版本是一次正常受理：账本返回一条未确认的报价结果并给出原因，而不是返回错误。

### 以保存的首次结果为准，不要按当前费率重算

- 非空请求标识的**首次**结果（无论确认还是拒绝）会被保存；之后相同标识、相同内容（费率项、版本、数量）的重试或 `Lookup` 查询都原样返回首次结果。
- 数量、版本来源（`Outcome.Request`）、单价（`UnitPrice`）和总价（`Total`）一律从首次结果读取。即使该版本后来被替代、单价变化，也**不能拿当前费率重新计算**——已确认记录永远保留确认时的值和首次受理时刻。
- 核对结论：`Lookup` 或原样重试取回的首次结果若 `Confirmed == true`，沿用原请求标识即可；若需要按新版本报价，必须使用一个**从未使用过的新标识**。

### 登记结束时间与实际有效结束时间可能不同

`ItemVersions` 同时返回两种边界：

- `End`：登记时填写的结束时刻（不含），永不因后续登记而改变；
- `EffectiveEnd`：**实际有效**结束时刻（不含）。当新版本通过 `Replaces` 替代旧版本时，旧版本的实际有效期被截断到新版本的生效时刻，因此 `EffectiveEnd` 可能早于登记的 `End`；旧版本若登记时未给结束时间，`End` 仍为 `nil`，而 `EffectiveEnd` 会显示交接点。

从交接时刻起，旧版本不能再接受新报价（新请求得到 `version_expired` 拒绝），但交接前已经确认的记录不受影响，仍保留原版本、数量、单价、总价和首次受理时刻。旧版本也不会在新版本到期后恢复生效。

### 首次拒绝同样幂等

对于非空标识，首次拒绝也会保存，可被 `Lookup` 查到：

- 若首次因**版本尚未生效**（`version_not_yet_effective`）被拒绝，即使之后版本已生效，用原标识原样重试仍返回那次首次拒绝（含首次受理时刻）。要按已生效的版本重新报价，必须换用新标识。
- 空标识的请求不保存（原因 `empty_request_id`），`Lookup("")` 返回未找到。

### 冲突与未找到

- 相同请求标识但改动了**费率项、版本或数量**：`Quote` 返回 `tariff.ErrRequestIDConflict`，原记录不被覆盖。
- 查询从未受理过的标识：`Lookup` 返回 `tariff.ErrRequestNotFound`。

### 结果只在当前账本实例内

报价记录保存在当前 `Book` 实例的内存中。重新 `NewBook()` 得到的是一本空账本，之前的标识全部查不到——不要假设跨实例仍能查询历史结果。

## 完整示例

下面的程序围绕同一费率项 `seat` 演示完整核对过程，代码位于
[`examples/reconcile/main.go`](examples/reconcile/main.go)，可直接运行：

```bash
go run ./examples/reconcile
```

示例通过公开选项 `tariff.WithClock` 注入一个可手动推进的时钟，因此输出确定、可复现：读者无需等待真实时间流逝，也不必自行编写时钟或补齐初始化代码。生产环境直接 `tariff.NewBook()` 即使用真实时间。

时间线：旧版本 `seat-v1` 单价 150 分，3 月 2 日在有效期内以数量 4 报价并确认总价 600 分；随后登记 3 月 10 日 00:00 起替代它的 `seat-v2`，并把受理时刻推进到交接点。

```go
// 命令 reconcile 是“费率变化后如何核对一笔报价”的完整可运行示例。
//
// 运行：
//
//	go run ./examples/reconcile
package main

import (
	"fmt"
	"time"

	"github.com/bengzyyys/tariff-book/tariff"
)

func main() {
	// 演示时钟：受理时刻取自变量 now，推进它即可让同一本账本走到不同时期。
	// 生产环境直接 tariff.NewBook() 即使用真实的 time.Now；
	// 这里传入 tariff.WithClock 只是为了让示例输出确定、可复现，无需等待真实时间。
	now := time.Date(2026, 3, 1, 9, 0, 0, 0, time.UTC)
	book := tariff.NewBook(tariff.WithClock(func() time.Time { return now }))

	// 登记旧版本 seat-v1：单价 150 分/单位，
	// 登记的有效期为 2026-03-01 至 2026-03-31（结束时刻不含）。
	oldEnd := time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
	must(book.RegisterVersion(tariff.RegisterRequest{
		ItemID:    "seat",
		VersionID: "seat-v1",
		UnitPrice: 150,
		Start:     time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC),
		End:       &oldEnd,
	}))

	// 2026-03-02 10:00，旧版本有效期内，用标识 quote-001 报价，数量 4。
	now = time.Date(2026, 3, 2, 10, 0, 0, 0, time.UTC)
	first, err := book.Quote(tariff.QuoteRequest{
		RequestID: "quote-001",
		ItemID:    "seat",
		VersionID: "seat-v1",
		Quantity:  4,
	})
	must(err)
	printOutcome("① 有效期内首次报价（quote-001）", first)

	// 登记新版本 seat-v2：单价 180，2026-03-10 00:00 起替代 seat-v1。
	must(book.RegisterVersion(tariff.RegisterRequest{
		ItemID:    "seat",
		VersionID: "seat-v2",
		UnitPrice: 180,
		Start:     time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC),
		Replaces:  "seat-v1",
	}))
	fmt.Println("② 新版本登记后的版本视图：")
	views, err := book.ItemVersions("seat")
	must(err)
	for _, v := range views {
		fmt.Printf("   %s：单价=%d 登记结束=%s 实际有效结束=%s 替代=%q 被替代=%q\n",
			v.VersionID, v.UnitPrice, fmtEnd(v.End), fmtEnd(v.EffectiveEnd),
			v.Replaces, v.SupersededBy)
	}

	// 将受理时刻推进到交接点本身（有效区间结束时刻不含该点）。
	now = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)

	got, err := book.Lookup("quote-001")
	must(err)
	printOutcome("③ 交接点按原标识 Lookup（quote-001）", got)
	fmt.Printf("   与首次结果完全一致：%v\n", got == first)

	replay, err := book.Quote(tariff.QuoteRequest{
		RequestID: "quote-001",
		ItemID:    "seat",
		VersionID: "seat-v1",
		Quantity:  4,
	})
	must(err)
	printOutcome("④ 交接点原样重试（quote-001）", replay)
	fmt.Printf("   与首次结果完全一致：%v\n", replay == first)

	fresh, err := book.Quote(tariff.QuoteRequest{
		RequestID: "quote-002",
		ItemID:    "seat",
		VersionID: "seat-v1",
		Quantity:  4,
	})
	must(err)
	printOutcome("⑤ 交接点用新标识引用旧版本（quote-002）", fresh)
	fmt.Printf("   本次返回 err==nil 但 Confirmed=%v，拒绝原因=%s，不能当作成功\n",
		fresh.Confirmed, fresh.Reason)

	// 再登记 seat-v3：2026-04-01 起替代 seat-v2，用于演示“版本尚未生效”的首次拒绝。
	must(book.RegisterVersion(tariff.RegisterRequest{
		ItemID:    "seat",
		VersionID: "seat-v3",
		UnitPrice: 200,
		Start:     time.Date(2026, 4, 1, 0, 0, 0, 0, time.UTC),
		Replaces:  "seat-v2",
	}))

	// 3 月 20 日：v3 尚未生效。非空标识的首次拒绝也会被保存。
	now = time.Date(2026, 3, 20, 9, 0, 0, 0, time.UTC)
	early, err := book.Quote(tariff.QuoteRequest{
		RequestID: "quote-003",
		ItemID:    "seat",
		VersionID: "seat-v3",
		Quantity:  4,
	})
	must(err)
	printOutcome("⑥ v3 生效前首次报价（quote-003）", early)

	// 推进到 4 月 2 日：v3 已生效，但原样重试仍返回 3 月 20 日的首次拒绝。
	now = time.Date(2026, 4, 2, 9, 0, 0, 0, time.UTC)
	earlyReplay, err := book.Quote(tariff.QuoteRequest{
		RequestID: "quote-003",
		ItemID:    "seat",
		VersionID: "seat-v3",
		Quantity:  4,
	})
	must(err)
	printOutcome("⑦ v3 生效后原样重试（quote-003）", earlyReplay)
	fmt.Printf("   与首次拒绝完全一致：%v（受理时刻仍是 %s）\n",
		earlyReplay == early, earlyReplay.AcceptedAt.Format(time.RFC3339))

	again, err := book.Quote(tariff.QuoteRequest{
		RequestID: "quote-004",
		ItemID:    "seat",
		VersionID: "seat-v3",
		Quantity:  4,
	})
	must(err)
	printOutcome("⑧ 改用新标识按 v3 重新报价（quote-004）", again)

	// 相同标识改动数量（改动费率项或版本同理）→ 请求内容冲突，原记录不被覆盖。
	_, err = book.Quote(tariff.QuoteRequest{
		RequestID: "quote-001",
		ItemID:    "seat",
		VersionID: "seat-v1",
		Quantity:  5,
	})
	fmt.Printf("⑨ 相同标识改数量：err=%v\n", err)
	unchanged, err := book.Lookup("quote-001")
	must(err)
	fmt.Printf("   原记录未被覆盖：Confirmed=%v 数量=%d 单价=%d 总价=%d\n",
		unchanged.Confirmed, unchanged.Request.Quantity, unchanged.UnitPrice, unchanged.Total)

	// 从未受理过的标识 → 未找到，这是 err 非空的情况。
	_, err = book.Lookup("quote-999")
	fmt.Printf("⑩ 查询从未受理的标识：err=%v\n", err)

	// 空标识：返回拒绝结果且 err 为 nil，但该拒绝不会保存。
	empty, err := book.Quote(tariff.QuoteRequest{ItemID: "seat", VersionID: "seat-v2", Quantity: 1})
	must(err)
	fmt.Printf("⑪ 空标识报价：Confirmed=%v 原因=%s err=%v\n", empty.Confirmed, empty.Reason, err)
	_, err = book.Lookup("")
	fmt.Printf("   空标识查询：err=%v（空标识的拒绝未保存）\n", err)

	// 报价结果只保存在当前账本实例内。
	freshBook := tariff.NewBook()
	_, err = freshBook.Lookup("quote-001")
	fmt.Printf("⑫ 新建账本查询 quote-001：err=%v\n", err)
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func fmtEnd(t *time.Time) string {
	if t == nil {
		return "无（持续有效）"
	}
	return t.Format(time.RFC3339)
}

func printOutcome(title string, o tariff.Outcome) {
	fmt.Printf("%s：\n", title)
	fmt.Printf("   请求 item=%s version=%s 数量=%d；首次受理时刻=%s\n",
		o.Request.ItemID, o.Request.VersionID, o.Request.Quantity,
		o.AcceptedAt.Format(time.RFC3339))
	if o.Confirmed {
		fmt.Printf("   结果=已确认 单价=%d 分 总价=%d 分\n", o.UnitPrice, o.Total)
	} else {
		fmt.Printf("   结果=被拒绝 原因=%s（err 为 nil，拒绝不是调用错误）\n", o.Reason)
	}
}
```

输出（时间为示例时钟推进到的确定时刻，不依赖真实时间）：

```text
① 有效期内首次报价（quote-001）：
   请求 item=seat version=seat-v1 数量=4；首次受理时刻=2026-03-02T10:00:00Z
   结果=已确认 单价=150 分 总价=600 分
② 新版本登记后的版本视图：
   seat-v1：单价=150 登记结束=2026-03-31T00:00:00Z 实际有效结束=2026-03-10T00:00:00Z 替代="" 被替代="seat-v2"
   seat-v2：单价=180 登记结束=无（持续有效） 实际有效结束=无（持续有效） 替代="seat-v1" 被替代=""
③ 交接点按原标识 Lookup（quote-001）：
