283		}
284		if got.Request.VersionID != "seat-v1" || got.Request.Quantity != 4 ||
285			got.UnitPrice != 150 || got.Total != 600 || !got.AcceptedAt.Equal(acceptedAt) {
286			t.Fatalf("历史报价未保留原版本/数量/金额/受理时刻: %+v", got)
287		}
