7	)
8	
9	// 连续替代场景的固定时间线（费率时间以东八区零点表示，结束时刻不含）：
10	//
11	//	甲版 seat-v1：单价 150 分，2026-03-01 起生效，登记结束 2026-03-31
12	//	乙版 seat-v2：单价 180 分，2026-03-10 起替代甲版，登记结束 2026-03-25
13	//	丙版 seat-v3：单价 200 分，2026-03-20 起替代乙版，登记结束 2026-03-24
14	//
15	// 乙版先登记成功后再登记丙版：乙版本身已替代过旧版，随后又被新版替代。
16	// 所有时刻写死并注入固定时钟，结论不依赖执行当天的真实日期。
17	var (
18		chainV1Start = time.Date(2026, 3, 1, 0, 0, 0, 0, east8)
19		chainV1End   = time.Date(2026, 3, 31, 0, 0, 0, 0, east8)
20		chainV2Start = time.Date(2026, 3, 10, 0, 0, 0, 0, east8)
21		chainV2End   = time.Date(2026, 3, 25, 0, 0, 0, 0, east8)
22		chainV3Start = time.Date(2026, 3, 20, 0, 0, 0, 0, east8)
23		chainV3End   = time.Date(2026, 3, 24, 0, 0, 0, 0, east8)
24	)
25	
26	// registerChainV1V2 依次登记甲版、乙版，建立第一次替代关系。
27	func registerChainV1V2(t *testing.T, b *Book) {
28		t.Helper()
29		v1End := chainV1End
30		if err := b.RegisterVersion(RegisterRequest{
31			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
32			Start: chainV1Start, End: &v1End,
33		}); err != nil {
34			t.Fatalf("register seat-v1: %v", err)
35		}
36		v2End := chainV2End
37		if err := b.RegisterVersion(RegisterRequest{
38			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
39			Start: chainV2Start, End: &v2End, Replaces: "seat-v1",
40		}); err != nil {
41			t.Fatalf("register seat-v2: %v", err)
42		}
43	}
44	
45	// registerChainV3 登记丙版替代乙版，建立第二次替代关系。
46	func registerChainV3(t *testing.T, b *Book) {
47		t.Helper()
48		v3End := chainV3End
49		if err := b.RegisterVersion(RegisterRequest{
50			ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200,
51			Start: chainV3Start, End: &v3End, Replaces: "seat-v2",
52		}); err != nil {
53			t.Fatalf("register seat-v3: %v", err)
54		}
55	}
56	
57	// newChainedBook 返回一本已完成甲→乙→丙连续替代的账本及其时钟。
58	func newChainedBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
59		t.Helper()
60		now, setNow := fixedClock(start)
61		b := NewBook(WithClock(now))
62		registerChainV1V2(t, b)
63		registerChainV3(t, b)
64		return b, setNow
65	}
66	
67	// 连续替代成功后的版本视图：三版按生效时刻排列；
68	// 甲版实际结束保持 3 月 10 日、被乙版替代的关系不变；
69	// 乙版同时显示替代甲版与被丙版替代，实际结束改为 3 月 20 日；
70	// 丙版显示替代乙版，实际结束为 3 月 24 日；三版登记结束都保留原值。
71	func TestChainedReplacementVersionView(t *testing.T) {
72		b, _ := newChainedBook(t, chainV1Start)
73	
74		views, err := b.ItemVersions("seat")
75		if err != nil {
76			t.Fatal(err)
77		}
78		if len(views) != 3 {
79			t.Fatalf("want 3 versions, got %d", len(views))
80		}
81		v1, v2, v3 := views[0], views[1], views[2]
82		if v1.VersionID != "seat-v1" || v2.VersionID != "seat-v2" || v3.VersionID != "seat-v3" {
83			t.Fatalf("版本应按生效时刻排列为 v1/v2/v3: %q, %q, %q",
84				v1.VersionID, v2.VersionID, v3.VersionID)
85		}
86	
87		// 甲版：登记结束仍是 3 月 31 日，实际结束保持第一次交接点 3 月 10 日，
88		// 被乙版替代的关系不因丙版登记而改变。
89		if v1.UnitPrice != 150 || !v1.Start.Equal(chainV1Start) {
90			t.Fatalf("甲版登记信息异常: %+v", v1)
91		}
92		if v1.End == nil || !v1.End.Equal(chainV1End) {
93			t.Fatalf("甲版登记结束应仍为 3 月 31 日: %v", v1.End)
94		}
95		if v1.EffectiveEnd == nil || !v1.EffectiveEnd.Equal(chainV2Start) {
96			t.Fatalf("甲版实际结束应保持 3 月 10 日: %v", v1.EffectiveEnd)
97		}
98		if v1.Replaces != "" || v1.SupersededBy != "seat-v2" {
99			t.Fatalf("甲版替代关系异常: Replaces=%q SupersededBy=%q", v1.Replaces, v1.SupersededBy)
100		}
101	
102		// 乙版：既显示替代甲版，又显示被丙版替代；
103		// 登记结束仍是 3 月 25 日，实际结束被第二次交接截断到 3 月 20 日。
104		if v2.UnitPrice != 180 || !v2.Start.Equal(chainV2Start) {
105			t.Fatalf("乙版登记信息异常: %+v", v2)
106		}
107		if v2.End == nil || !v2.End.Equal(chainV2End) {
108			t.Fatalf("乙版登记结束应仍为 3 月 25 日: %v", v2.End)
109		}
110		if v2.EffectiveEnd == nil || !v2.EffectiveEnd.Equal(chainV3Start) {
111			t.Fatalf("乙版实际结束应为第二次交接点 3 月 20 日: %v", v2.EffectiveEnd)
112		}
113		if v2.Replaces != "seat-v1" || v2.SupersededBy != "seat-v3" {
114			t.Fatalf("乙版应同时显示替代甲版与被丙版替代: Replaces=%q SupersededBy=%q",
115				v2.Replaces, v2.SupersededBy)
116		}
117	
118		// 丙版：显示替代乙版，登记结束与实际结束都是 3 月 24 日。
119		if v3.UnitPrice != 200 || !v3.Start.Equal(chainV3Start) {
120			t.Fatalf("丙版登记信息异常: %+v", v3)
121		}
122		if v3.End == nil || !v3.End.Equal(chainV3End) {
123			t.Fatalf("丙版登记结束应为 3 月 24 日: %v", v3.End)
124		}
125		if v3.EffectiveEnd == nil || !v3.EffectiveEnd.Equal(chainV3End) {
126			t.Fatalf("丙版实际结束应为 3 月 24 日: %v", v3.EffectiveEnd)
127		}
128		if v3.Replaces != "seat-v2" || v3.SupersededBy != "" {
129			t.Fatalf("丙版替代关系异常: Replaces=%q SupersededBy=%q", v3.Replaces, v3.SupersededBy)
130		}
131	}
132	
133	// 第二次交接前后的报价行为：3 月 19 日乙版以数量 4 确认 720 分；
134	// 3 月 20 日起引用乙版（新的请求标识）返回 version_expired 拒绝，
135	// 引用丙版确认 800 分；拒绝是正常受理而非调用错误，金额为零且保留指定版本。
136	func TestChainedReplacementQuotesAcrossSecondHandoff(t *testing.T) {
137		b, setNow := newChainedBook(t, chainV1Start)
138	
139		// 第二次交接前：乙版仍有效，数量 4 确认 180*4=720 分。
140		setNow(time.Date(2026, 3, 19, 0, 0, 0, 0, east8))
141		before, err := b.Quote(QuoteRequest{
142			RequestID: "chain-before", ItemID: "seat", VersionID: "seat-v2", Quantity: 4,
143		})
144		if err != nil {
145			t.Fatalf("确认是正常受理，err 应为空: %v", err)
146		}
147		if !before.Confirmed || before.UnitPrice != 180 || before.Total != 720 {
148			t.Fatalf("3 月 19 日乙版报价应确认 720 分: %+v", before)
149		}
150	
151		// 第二次交接点：乙版已失效，丙版生效。
152		setNow(chainV3Start)
153	
154		expiredReq := QuoteRequest{
155			RequestID: "chain-v2-expired", ItemID: "seat", VersionID: "seat-v2", Quantity: 4,
156		}
157		expired, err := b.Quote(expiredReq)
158		if err != nil {
159			t.Fatalf("拒绝是正常受理，err 应为空: %v", err)
160		}
161		if expired.Confirmed || expired.Reason != ReasonVersionExpired {
162			t.Fatalf("3 月 20 日引用乙版应返回 version_expired 拒绝: %+v", expired)
163		}
164		if expired.UnitPrice != 0 || expired.Total != 0 {
165			t.Fatalf("拒绝结果单价/总价应为零: 单价=%d 总价=%d", expired.UnitPrice, expired.Total)
166		}
167		if expired.Request != expiredReq {
168			t.Fatalf("拒绝结果必须保留调用者指定的版本等请求内容: %+v vs %+v", expired.Request, expiredReq)
169		}
170	
171		confirmed, err := b.Quote(QuoteRequest{
172			RequestID: "chain-v3-800", ItemID: "seat", VersionID: "seat-v3", Quantity: 4,
173		})
174		if err != nil {
175			t.Fatalf("确认是正常受理，err 应为空: %v", err)
176		}
177		if !confirmed.Confirmed || confirmed.UnitPrice != 200 || confirmed.Total != 800 {
178			t.Fatalf("3 月 20 日丙版报价应确认 800 分: %+v", confirmed)
179		}
180	}
181	
182	// 第二次交接前已确认的乙版报价，在丙版登记之后查询仍是
183	// 原请求、原金额和原受理时刻，不随丙版登记或时间推进改变。
184	func TestChainedReplacementConfirmedQuoteSurvives(t *testing.T) {
185		now, setNow := fixedClock(chainV1Start)
186		b := NewBook(WithClock(now))
187		registerChainV1V2(t, b)
188	
189		// 第二次交接前、丙版尚未登记时确认乙版报价。
190		acceptedAt := time.Date(2026, 3, 19, 0, 0, 0, 0, east8)
191		setNow(acceptedAt)
192		req := QuoteRequest{RequestID: "chain-keep-720", ItemID: "seat", VersionID: "seat-v2", Quantity: 4}
193		first, err := b.Quote(req)
194		if err != nil || !first.Confirmed {
195			t.Fatalf("交接前报价应确认: %v %+v", err, first)
196		}
197		if first.UnitPrice != 180 || first.Total != 720 {
198			t.Fatalf("交接前金额: 单价=%d 总价=%d", first.UnitPrice, first.Total)
199		}
200		if !first.AcceptedAt.Equal(acceptedAt) {
201			t.Fatalf("首次受理时刻: %v", first.AcceptedAt)
202		}
203	
204		// 随后登记丙版并推进到第二次交接点之后：乙版已失效，丙版 200 分已生效。
205		registerChainV3(t, b)
206		setNow(chainV3Start.Add(24 * time.Hour))
207	
208		got, err := b.Lookup("chain-keep-720")
209		if err != nil {
210			t.Fatal(err)
211		}
212		if got != first {
213			t.Fatalf("历史报价被丙版登记改写: %+v -> %+v", first, got)
214		}
215		if got.Request != req || got.UnitPrice != 180 || got.Total != 720 ||
216			!got.AcceptedAt.Equal(acceptedAt) {
217			t.Fatalf("历史报价未保留原请求/金额/受理时刻: %+v", got)
218		}
219	
220		// 原样重试同样返回首次结果，而不是按当前费率重算或改判拒绝。
221		replay, err := b.Quote(req)
222		if err != nil {
223			t.Fatal(err)
224		}
225		if replay != first {
226			t.Fatalf("重试结果被改写: %+v -> %+v", first, replay)
227		}
228	}
229	
230	// 第二次替代选错来源：丙版同样从 3 月 20 日开始却填写替代甲版，
231	// 即使甲版登记结束仍是 3 月 31 日，也必须返回 ErrInvalidReplacement；
232	// 失败不改变甲、乙两版的实际结束与替代关系，也不留下丙版；
233	// 随后沿用丙版标识改为替代乙版，仍可按原条件成功。
234	func TestChainedReplacementWrongSourceThenFixed(t *testing.T) {
235		now, _ := fixedClock(chainV1Start)
236		b := NewBook(WithClock(now))
237		registerChainV1V2(t, b)
238	
239		v3End := chainV3End
240		err := b.RegisterVersion(RegisterRequest{
241			ItemID: "seat", VersionID: "seat-v3", UnitPrice: 200,
242			Start: chainV3Start, End: &v3End, Replaces: "seat-v1",
243		})
244		if !errors.Is(err, ErrInvalidReplacement) {
245			t.Fatalf("替代已被截断的甲版应返回 ErrInvalidReplacement, got %v", err)
246		}
247	
248		// 失败不留痕迹：仍只有甲、乙两版，边界与替代关系保持第一次交接后的状态。
249		views, err := b.ItemVersions("seat")
250		if err != nil {
251			t.Fatal(err)
252		}
253		if len(views) != 2 {
254			t.Fatalf("失败登记后应仍只有两个版本，got %d: %+v", len(views), views)
255		}
256		v1, v2 := views[0], views[1]
257		if v1.VersionID != "seat-v1" || v2.VersionID != "seat-v2" {
258			t.Fatalf("失败登记后版本集合/顺序异常: %q, %q", v1.VersionID, v2.VersionID)
259		}
260		if v1.End == nil || !v1.End.Equal(chainV1End) {
261			t.Fatalf("甲版登记结束被改写: %v", v1.End)
262		}
263		if v1.EffectiveEnd == nil || !v1.EffectiveEnd.Equal(chainV2Start) {
264			t.Fatalf("甲版实际结束应仍为 3 月 10 日: %v", v1.EffectiveEnd)
265		}
266		if v1.Replaces != "" || v1.SupersededBy != "seat-v2" {
267			t.Fatalf("甲版替代关系被改写: Replaces=%q SupersededBy=%q", v1.Replaces, v1.SupersededBy)
268		}
269		if v2.End == nil || !v2.End.Equal(chainV2End) {
270			t.Fatalf("乙版登记结束被改写: %v", v2.End)
271		}
272		if v2.EffectiveEnd == nil || !v2.EffectiveEnd.Equal(chainV2End) {
273			t.Fatalf("乙版实际结束不能被失败登记提前截断，应仍为 3 月 25 日: %v", v2.EffectiveEnd)
274		}
275		if v2.Replaces != "seat-v1" || v2.SupersededBy != "" {
276			t.Fatalf("乙版替代关系被改写: Replaces=%q SupersededBy=%q", v2.Replaces, v2.SupersededBy)
277		}
278	
279		// 沿用丙版标识，改为替代乙版，按原条件登记成功。
280		registerChainV3(t, b)
281	
282		views, err = b.ItemVersions("seat")
283		if err != nil {
284			t.Fatal(err)
285		}
286		if len(views) != 3 {
287			t.Fatalf("修正后应有三个版本, got %d", len(views))
288		}
289		v1, v2, v3 := views[0], views[1], views[2]
290		if v1.VersionID != "seat-v1" || v2.VersionID != "seat-v2" || v3.VersionID != "seat-v3" {
291			t.Fatalf("修正后版本集合/顺序异常: %q, %q, %q", v1.VersionID, v2.VersionID, v3.VersionID)
292		}
293		if v1.EffectiveEnd == nil || !v1.EffectiveEnd.Equal(chainV2Start) ||
294			v1.SupersededBy != "seat-v2" {
295			t.Fatalf("甲版实际结束与替代关系应保持不变: %+v", v1)
296		}
297		if v2.EffectiveEnd == nil || !v2.EffectiveEnd.Equal(chainV3Start) ||
298			v2.Replaces != "seat-v1" || v2.SupersededBy != "seat-v3" {
299			t.Fatalf("乙版应被截断到 3 月 20 日并显示双向替代关系: %+v", v2)
300		}
301		if v3.Replaces != "seat-v2" || v3.EffectiveEnd == nil || !v3.EffectiveEnd.Equal(chainV3End) {
302			t.Fatalf("丙版应显示替代乙版、实际结束 3 月 24 日: %+v", v3)
303		}
304	}
