9	// 不同费率项复用同一版本标识时，一次替代登记只能作用于请求指定费率项内的同名版本：
10	// 另一项存在同名版本，不能影响来源选择、交接是否合法，也不能被改写边界或替代关系。
11	//
12	// 固定时间线（UTC，结束时刻均不含）：
13	//
14	//	seat/v1：单价 150 分，2026-03-01 至 2026-03-31
15	//	room/v1：单价 300 分，2026-02-15 至 2026-05-31
16	//	        （与 seat/v1 有效期重叠，但跨费率项重叠不是冲突）
17	//	拟交接点：2026-03-10 00:00
18	var (
19		crossSeatV1Start = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
20		crossSeatV1End   = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
21		crossRoomV1Start = time.Date(2026, 2, 15, 0, 0, 0, 0, time.UTC)
