26	// newCrossItemSameVersionBook 在同一本账本中为 seat、room 各登记一个名为 v1 的版本，
27	// 两者单价和结束时间不同、有效期重叠——复用版本标识与跨项重叠都应允许。
28	func newCrossItemSameVersionBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
29		t.Helper()
30		now, setNow := fixedClock(start)
31		b := NewBook(WithClock(now))
32		seatEnd := crossSeatV1End
