38		}
39		roomEnd := crossRoomV1End
40		if err := b.RegisterVersion(RegisterRequest{
41			ItemID: "room", VersionID: "v1", UnitPrice: 300,
42			Start: crossRoomV1Start, End: &roomEnd,
43		}); err != nil {
44			t.Fatalf("不同费率项应能复用版本标识且有效期重叠: %v", err)
45		}
46		return b, setNow
47	}
48	
49	// findVersionView 在指定费率项的视图中找出指定版本，找不到则让测试失败。
50	func findVersionView(t *testing.T, b *Book, itemID, versionID string) VersionView {
51		t.Helper()
52		views, err := b.ItemVersions(itemID)
53		if err != nil {
54			t.Fatalf("ItemVersions(%q): %v", itemID, err)
55		}
56		for _, v := range views {
57			if v.VersionID == versionID {
58				return v
59			}
60		}
61		t.Fatalf("费率项 %q 下不存在版本 %q，实际版本视图: %+v", itemID, versionID, views)
62		return VersionView{}
