65	// 给 seat 登记 v2 替代 seat 自己的 v1：截断与替代关系只发生在本项两版之间，
66	// room 的同名 v1 单价、登记结束、实际结束和替代关系全部保持不变；
67	// 交接时刻两项各自的新报价只按各自版本的状态受理。
68	func TestReplacementScopedToRequestedItem(t *testing.T) {
69		b, setNow := newCrossItemSameVersionBook(t, crossHandoff)
70	
71		if err := b.RegisterVersion(RegisterRequest{
72			ItemID: "seat", VersionID: "v2", UnitPrice: 180,
