78		// seat/v1：单价不变，登记结束保留 3 月 31 日，实际结束截断到交接点 3 月 10 日。
79		seatV1 := findVersionView(t, b, "seat", "v1")
80		if seatV1.UnitPrice != 150 {
81			t.Fatalf("seat/v1 单价被改写: %d", seatV1.UnitPrice)
82		}
83		if seatV1.End == nil || !seatV1.End.Equal(crossSeatV1End) {
84			t.Fatalf("seat/v1 登记结束应保留原值 3 月 31 日: %v", seatV1.End)
85		}
86		if seatV1.EffectiveEnd == nil || !seatV1.EffectiveEnd.Equal(crossHandoff) {
87			t.Fatalf("seat/v1 实际结束应为交接点 3 月 10 日: %v", seatV1.EffectiveEnd)
88		}
89		if seatV1.Replaces != "" || seatV1.SupersededBy != "v2" {
90			t.Fatalf("seat/v1 替代关系异常: Replaces=%q SupersededBy=%q",
91				seatV1.Replaces, seatV1.SupersededBy)
92		}
93	
94		// seat/v2：替代来源对应本项的 v1，单价为新登记值。
95		seatV2 := findVersionView(t, b, "seat", "v2")
96		if seatV2.UnitPrice != 180 || seatV2.Replaces != "v1" || seatV2.SupersededBy != "" {
97			t.Fatalf("seat/v2 登记信息异常: %+v", seatV2)
98		}
99	
100		// room/v1：单价、登记结束、实际结束、替代关系都不受另一项交接影响，也不冒出新版本。
101		roomV1 := findVersionView(t, b, "room", "v1")
102		if roomV1.UnitPrice != 300 {
103			t.Fatalf("room/v1 单价被另一项的替代登记改写: %d", roomV1.UnitPrice)
104		}
105		if roomV1.End == nil || !roomV1.End.Equal(crossRoomV1End) {
106			t.Fatalf("room/v1 登记结束被改写: %v", roomV1.End)
