134			t.Fatalf("seat/v1 拒绝原因=%q, want %q", seatOut.Reason, ReasonVersionExpired)
135		}
136		if seatOut.UnitPrice != 0 || seatOut.Total != 0 {
137			t.Fatalf("拒绝结果单价/总价应为零: %d/%d", seatOut.UnitPrice, seatOut.Total)
138		}
