172	// 本项 v1 在拟定交接时刻已经结束，而另一项的同名 v1 当时仍有效：
173	// 替代是否合法只以本项已有来源的实际有效区间为依据，必须返回 ErrInvalidReplacement，
174	// 不能借另一项仍有效的同名版本通过校验，也不能把来源说成属于另一项。
175	// 结束时刻本身不属于有效期（半开区间 [start, end)）。
176	func TestReplacementJudgedByOwnEndedVersionNotOtherItemLiveOne(t *testing.T) {
177		now, setNow := fixedClock(crossSeatV1Start)
