210		// 这两个开始时刻与 seat/v1 区间仅相邻或更晚，不会触发 ErrOverlap，
211		// 唯一正确的结论是替代窗口校验失败。
212		cases := []struct {
213			name  string
214			start time.Time
215		}{
216			{"交接时刻等于本项版本结束时刻（结束时刻不含）", crossHandoff},
217			{"交接时刻晚于本项版本结束时刻", crossHandoff.Add(24 * time.Hour)},
218		}
219		for _, c := range cases {
220			err := b.RegisterVersion(RegisterRequest{
221				ItemID: "seat", VersionID: "v2", UnitPrice: 180,
222				Start: c.start, Replaces: "v1",
223			})
224			if !errors.Is(err, ErrInvalidReplacement) {
225				t.Fatalf("%s: 必须按本项 v1 已结束返回 ErrInvalidReplacement, got %v", c.name, err)
226			}
227			if errors.Is(err, ErrReplaceTargetWrongItem) {
228				t.Fatalf("%s: 替代来源就在本项，不能借另一项同名版本说成来源属于另一项: %v",
229					c.name, err)
230			}
231		}
