233		// 失败后：两项都不出现失败的新版本 v2，旧版时间边界与替代关系与登记前一致。
234		seatViews, err := b.ItemVersions("seat")
235		if err != nil {
236			t.Fatal(err)
237		}
238		if len(seatViews) != 1 || seatViews[0].VersionID != "v1" {
239			t.Fatalf("失败登记后 seat 应仍只有 v1: %+v", seatViews)
240		}
241		if seatViews[0].UnitPrice != 150 ||
242			seatViews[0].End == nil || !seatViews[0].End.Equal(crossHandoff) ||
243			seatViews[0].EffectiveEnd == nil || !seatViews[0].EffectiveEnd.Equal(crossHandoff) ||
244			seatViews[0].Replaces != "" || seatViews[0].SupersededBy != "" {
245			t.Fatalf("seat/v1 边界或替代关系被失败登记改写: %+v", seatViews[0])
246		}
247		roomViews, err := b.ItemVersions("room")
248		if err != nil {
249			t.Fatal(err)
250		}
251		if len(roomViews) != 1 || roomViews[0].VersionID != "v1" {
252			t.Fatalf("失败登记不能波及 room 的版本集合: %+v", roomViews)
253		}
254		if roomViews[0].UnitPrice != 300 ||
255			roomViews[0].End == nil || !roomViews[0].End.Equal(crossRoomV1End) ||
256			roomViews[0].EffectiveEnd == nil || !roomViews[0].EffectiveEnd.Equal(crossRoomV1End) ||
257			roomViews[0].Replaces != "" || roomViews[0].SupersededBy != "" {
258			t.Fatalf("room/v1 边界或替代关系被另一项的失败登记改写: %+v", roomViews[0])
259		}
260	
261		// room 既有确认记录的金额与来源不被失败登记改变。
262		got, err := b.Lookup(firstReq.RequestID)
263		if err != nil {
264			t.Fatal(err)
265		}
266		if got != first {
267			t.Fatalf("room 既有确认记录被改写: %+v -> %+v", first, got)
268		}
269	
270		// 交接时刻用各自的新标识、正数量再报价：seat/v1 正常受理但 version_expired；
271		// room/v1 仍按自己的 300 分单价确认，金额与来源都不受失败登记影响。
272		setNow(crossHandoff)
273	
274		seatReq := QuoteRequest{
275			RequestID: "seat-v1-expired-at-handoff", ItemID: "seat", VersionID: "v1", Quantity: 4,
276		}
277		seatOut, err := b.Quote(seatReq)
278		if err != nil {
279			t.Fatalf("版本拒绝是正常受理，err 应为空: %v", err)
280		}
281		if seatOut.Confirmed || seatOut.Reason != ReasonVersionExpired {
282			t.Fatalf("seat/v1 在结束时刻应 version_expired 拒绝: %+v", seatOut)
283		}
284		if seatOut.UnitPrice != 0 || seatOut.Total != 0 {
285			t.Fatalf("拒绝结果单价/总价应为零: %d/%d", seatOut.UnitPrice, seatOut.Total)
286		}
287		if seatOut.Request != seatReq {
288			t.Fatalf("拒绝结果来源必须仍是 seat/v1: %+v vs %+v", seatOut.Request, seatReq)
289		}
290	
291		roomReq := QuoteRequest{
292			RequestID: "room-v1-still-live-at-handoff", ItemID: "room", VersionID: "v1", Quantity: 3,
293		}
294		roomOut, err := b.Quote(roomReq)
295		if err != nil {
296			t.Fatalf("room/v1 报价不应返回错误: %v", err)
297		}
298		if !roomOut.Confirmed || roomOut.Reason != ReasonNone {
299			t.Fatalf("room/v1 应正常确认: %+v", roomOut)
300		}
301		if roomOut.UnitPrice != 300 || roomOut.Total != 900 {
302			t.Fatalf("room/v1 应按自己的单价 300 成交: 单价=%d 总价=%d, want 300/900",
303				roomOut.UnitPrice, roomOut.Total)
304		}
305		if roomOut.Request != roomReq {
306			t.Fatalf("报价来源必须保持 room/v1: %+v vs %+v", roomOut.Request, roomReq)
307		}
308	}
309	
310	// 本项根本没有所填的替代来源，只有其他费率项存在该版本标识：
311	// 按既有语义返回 ErrReplaceTargetWrongItem；失败不留任何痕迹，也不影响另一项报价。
312	func TestReplacementTargetMissingInItemOnlyExistsInOtherItem(t *testing.T) {
313		now, setNow := fixedClock(crossSeatV1Start)
314		b := NewBook(WithClock(now))
315	
316		// seat 只有 v0（3 月 5 日结束）；名为 v1 的版本只存在于 room。
317		v0End := time.Date(2026, 3, 5, 0, 0, 0, 0, time.UTC)
318		if err := b.RegisterVersion(RegisterRequest{
319			ItemID: "seat", VersionID: "v0", UnitPrice: 100,
320			Start: crossSeatV1Start, End: &v0End,
321		}); err != nil {
322			t.Fatalf("register seat/v0: %v", err)
323		}
324		roomEnd := crossRoomV1End
325		if err := b.RegisterVersion(RegisterRequest{
326			ItemID: "room", VersionID: "v1", UnitPrice: 300,
327			Start: crossRoomV1Start, End: &roomEnd,
328		}); err != nil {
329			t.Fatalf("register room/v1: %v", err)
330		}
331	
332		// 拟交接点 3 月 10 日落在 room/v1 有效期内，却在 seat 中找不到来源 v1：
333		// 不能拿 room 的 v1 当来源，必须按既有含义报错。
334		if err := b.RegisterVersion(RegisterRequest{
335			ItemID: "seat", VersionID: "v2", UnitPrice: 180,
336			Start: crossHandoff, Replaces: "v1",
337		}); !errors.Is(err, ErrReplaceTargetWrongItem) {
338			t.Fatalf("本项无 v1、另一项有同名 v1: want ErrReplaceTargetWrongItem, got %v", err)
339		}
340	
341		// 费率项本身都不存在时，语义相同：同名版本只在别的项里。
342		if err := b.RegisterVersion(RegisterRequest{
343			ItemID: "hall", VersionID: "v9", UnitPrice: 1,
344			Start: crossHandoff, Replaces: "v1",
345		}); !errors.Is(err, ErrReplaceTargetWrongItem) {
346			t.Fatalf("不存在的费率项也应返回 ErrReplaceTargetWrongItem, got %v", err)
347		}
348	
349		// 失败不留痕：seat 仍只有 v0，room 仍只有 v1，hall 未被创建。
350		seatViews, err := b.ItemVersions("seat")
351		if err != nil {
352			t.Fatal(err)
353		}
354		if len(seatViews) != 1 || seatViews[0].VersionID != "v0" {
355			t.Fatalf("失败登记不能在 seat 留下 v2 或 v1: %+v", seatViews)
356		}
357		if seatViews[0].UnitPrice != 100 ||
358			seatViews[0].End == nil || !seatViews[0].End.Equal(v0End) ||
359			seatViews[0].EffectiveEnd == nil || !seatViews[0].EffectiveEnd.Equal(v0End) ||
360			seatViews[0].Replaces != "" || seatViews[0].SupersededBy != "" {
361			t.Fatalf("seat/v0 被失败登记改写: %+v", seatViews[0])
362		}
363		roomViews, err := b.ItemVersions("room")
364		if err != nil {
365			t.Fatal(err)
366		}
367		if len(roomViews) != 1 {
368			t.Fatalf("room 版本集合被失败登记波及: %+v", roomViews)
369		}
370		if roomViews[0].UnitPrice != 300 ||
371			roomViews[0].End == nil || !roomViews[0].End.Equal(crossRoomV1End) ||
372			roomViews[0].EffectiveEnd == nil || !roomViews[0].EffectiveEnd.Equal(crossRoomV1End) ||
373			roomViews[0].Replaces != "" || roomViews[0].SupersededBy != "" {
374			t.Fatalf("room/v1 被失败登记改写: %+v", roomViews[0])
375		}
376		if _, err := b.ItemVersions("hall"); !errors.Is(err, ErrItemNotFound) {
377			t.Fatalf("失败登记不应凭空创建 hall 费率项: %v", err)
378		}
379	
380		// 交接时刻的报价不受失败登记影响。
381		setNow(crossHandoff)
382	
383		// seat/v1 确实不存在：正常受理（err 为空）的 version_not_found 拒绝，金额为零。
384		missingReq := QuoteRequest{
385			RequestID: "seat-v1-never-registered", ItemID: "seat", VersionID: "v1", Quantity: 4,
386		}
387		missingOut, err := b.Quote(missingReq)
388		if err != nil {
389			t.Fatalf("版本未找到的拒绝是正常受理，err 应为空: %v", err)
390		}
391		if missingOut.Confirmed || missingOut.Reason != ReasonVersionNotFound {
392			t.Fatalf("seat/v1 应 version_not_found 拒绝: %+v", missingOut)
393		}
394		if missingOut.UnitPrice != 0 || missingOut.Total != 0 {
395			t.Fatalf("拒绝结果单价/总价应为零: %d/%d", missingOut.UnitPrice, missingOut.Total)
396		}
397		if missingOut.Request != missingReq {
398			t.Fatalf("拒绝结果来源必须保留请求内容: %+v vs %+v", missingOut.Request, missingReq)
399		}
400	
401		// room/v1 仍按自己的单价确认，金额与来源保持不变。
402		roomReq := QuoteRequest{
403			RequestID: "room-v1-unaffected-at-handoff", ItemID: "room", VersionID: "v1", Quantity: 4,
404		}
405		roomOut, err := b.Quote(roomReq)
406		if err != nil {
407			t.Fatalf("room/v1 报价不应返回错误: %v", err)
408		}
409		if !roomOut.Confirmed || roomOut.UnitPrice != 300 || roomOut.Total != 1200 {
410			t.Fatalf("room/v1 应按 300 分单价确认总价 1200: %+v", roomOut)
411		}
412		if roomOut.Request != roomReq {
413			t.Fatalf("报价来源必须保持 room/v1: %+v vs %+v", roomOut.Request, roomReq)
414		}
415	
416		// 失败登记不占用新版本标识：去掉错误来源后，seat/v2 在与 v0 不重叠的 3 月 10 日可正常登记。
417		if err := b.RegisterVersion(RegisterRequest{
418			ItemID: "seat", VersionID: "v2", UnitPrice: 180, Start: crossHandoff,
419		}); err != nil {
420			t.Fatalf("失败的登记不应占用版本标识 v2: %v", err)
421		}
422		seatV2 := findVersionView(t, b, "seat", "v2")
423		if seatV2.Replaces != "" || seatV2.SupersededBy != "" || seatV2.UnitPrice != 180 {
424			t.Fatalf("重新登记的 seat/v2 不应带有失败时填写的替代来源: %+v", seatV2)
425		}
426	}
